<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {api} from '../api';import Modal from '../components/Modal.vue';import type {WorkTab} from '../stores';
const props=defineProps<{tab:WorkTab;embedded?:boolean}>(),month=ref(props.tab.month),type=ref('all'),size=ref('100'),data=ref<any>(null),loading=ref(false),error=ref('');
const exporting=ref(false);
const types=ref<{value:string;label:string}[]>([]);
const changed=computed(()=>data.value&&(month.value!==data.value.month||type.value!==data.value.type||Number(size.value)!==data.value.size));
const pages=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/Number(data.value?.size||100))));
async function load(page=1){if(loading.value)return;loading.value=true;error.value='';data.value=null;try{const result=await api('employee-movements?'+new URLSearchParams({month:month.value,type:type.value,size:size.value,page:String(page)}));data.value=result;types.value=result.types;props.tab.month=result.month;props.tab.title='異動紀錄 · '+(result.month||'全部月份');}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function download(){if(exporting.value||loading.value||changed.value||!data.value?.rows.length)return;exporting.value=true;error.value='';const snapshot=data.value;
 try{const {movementWorkbook}=await import('../employee-export');const url=URL.createObjectURL(new Blob([movementWorkbook(snapshot.rows)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download=`人員異動記錄_${snapshot.month||'全部月份'}_第${snapshot.page}頁.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{error.value='Excel 匯出失敗，請重試。';}finally{exporting.value=false;}}
const editing=ref<any>(null),form=ref<any>({}),removing=ref<any>(null),saving=ref(false),dialogError=ref(''),notice=ref('');
const dateTail=(v:string)=>String(v||'').slice(0,10);
function levelOf(r:any){return (String(r.notes||'').match(/(?:新人等級|行政階級)[:：]([^；\n]+)/)?.[1]||'').trim();}
function openEdit(r:any){dialogError.value='';notice.value='';editing.value=r;form.value={employee_name:r.employee_name,movement_date:dateTail(r.movement_date),notes:r.display_notes||'',position:r.movement_type==='promotion'?r.new_value:'',newbie_level:r.movement_type==='promotion'?levelOf(r):'',onboarding_is_pharmacist:!!r.onboarding_is_pharmacist};}
const levelOptions=computed(()=>form.value.position==='新人'?data.value?.newbieLevels||[]:form.value.position==='行政'?data.value?.adminLevels||[]:[]);
async function saveEdit(){if(saving.value||!editing.value)return;saving.value=true;dialogError.value='';const r=editing.value;
 try{const body:any={employee_name:form.value.employee_name,movement_date:form.value.movement_date,notes:form.value.notes};if(r.movement_type==='promotion'){body.position=form.value.position;body.newbie_level=['新人','行政'].includes(form.value.position)?form.value.newbie_level:'';}if(r.movement_type==='onboarding')body.onboarding_is_pharmacist=!!form.value.onboarding_is_pharmacist;
  const res=await api('employee-movements/'+r.id,{method:'PATCH',body:JSON.stringify(body)});editing.value=null;notice.value=res.message||'已更新';await load(data.value?.page||1);}catch(e){dialogError.value=(e as Error).message;}finally{saving.value=false;}}
function openRemove(r:any){dialogError.value='';notice.value='';removing.value=r;}
async function confirmRemove(){if(saving.value||!removing.value)return;saving.value=true;dialogError.value='';
 try{const res=await api('employee-movements/'+removing.value.id,{method:'DELETE'});removing.value=null;notice.value=res.message||'已刪除';await load(data.value?.page||1);}catch(e){dialogError.value=(e as Error).message;}finally{saving.value=false;}}
const showActions=computed(()=>!!(data.value?.canEdit||data.value?.canDelete));
defineExpose({refresh:()=>load(data.value?.page||1)});
onMounted(()=>load());
</script>
<template><header class="page-heading"><div><p v-if="!embedded" class="eyebrow">組織與門市 / 人員異動管理</p><h1 v-if="!embedded">人員異動紀錄</h1></div><button :disabled="loading" @click="load()">重新整理</button></header>
<form class="filters" @submit.prevent="load()"><label>生效月份<input type="month" v-model="month" :disabled="loading"></label><button type="button" :disabled="loading" @click="month='';load()">全部月份</button><label>異動類型<select v-model="type" aria-label="異動類型" :disabled="loading"><option value="all">全部類型</option><option v-for="t in types" :key="t.value" :value="t.value">{{t.label}}</option></select></label><label>每頁筆數<select v-model="size" aria-label="每頁筆數" :disabled="loading"><option>50</option><option>100</option></select></label><button class="primary" :disabled="loading">查詢紀錄</button></form>
<p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="loading" role="status">正在查詢異動紀錄…</p><p v-if="notice" class="notice" role="status" data-testid="movement-notice">{{notice}}</p><p v-if="changed" class="notice">條件已變更，請查詢紀錄以更新結果。</p>
<template v-if="data"><div class="result-heading"><p>{{data.month||'全部月份'}} · {{data.types.find((t:any)=>t.value===data.type)?.label||'全部類型'}} · 共 {{data.total}} 筆</p><button :disabled="exporting||changed||!data.rows.length" @click="download">{{exporting?'正在匯出…':'匯出本頁 Excel'}}</button></div><div class="module-table"><table><thead><tr><th>生效日期</th><th>員編／姓名</th><th>任職門市</th><th>類型</th><th>入職藥師</th><th>原值</th><th>新值</th><th>備註</th><th v-if="showActions">操作</th></tr></thead><tbody><tr v-for="r in data.rows" :key="r.id"><td>{{r.movement_date}}</td><td>{{r.employee_code}}<br>{{r.employee_name}}</td><td>{{r.store?.store_code}} {{r.store?.store_name||'未指定門市'}}</td><td>{{r.type_label}}</td><td>{{r.movement_type==='onboarding'?(r.onboarding_is_pharmacist===null?'未記錄':r.onboarding_is_pharmacist?'是':'否'):'—'}}</td><td>{{r.old_value||'—'}}</td><td>{{r.new_label||'—'}}</td><td class="notes">{{r.display_notes||'—'}}</td><td v-if="showActions" class="actions" data-label="操作"><button v-if="data.canEdit" :disabled="loading||changed" data-testid="movement-edit" @click="openEdit(r)">修改</button><template v-if="data.canDelete"><button :disabled="loading||changed||!r.is_latest" data-testid="movement-delete" :aria-describedby="r.is_latest?undefined:'latest-only-'+r.id" @click="openRemove(r)">刪除</button><span v-if="!r.is_latest" :id="'latest-only-'+r.id" class="hint" data-testid="movement-delete-hint">此員工有更晚的異動，請先刪除較新的一筆</span></template></td></tr><tr v-if="!data.rows.length"><td :colspan="showActions?9:8">沒有符合條件的異動紀錄。</td></tr></tbody></table></div><div class="pagination"><span>第 {{data.page}} / {{pages}} 頁</span><button :disabled="loading||changed||data.page===1" @click="load(data.page-1)">上一頁</button><button :disabled="loading||changed||data.page>=pages" @click="load(data.page+1)">下一頁</button></div></template>
<Modal v-if="editing" title="修改異動紀錄" :busy="saving" @cancel="editing=null"><p>{{editing.employee_code}} · {{editing.type_label}}（類型與門市不可修改）</p>
 <form class="edit-form" @submit.prevent="saveEdit"><p v-if="dialogError" class="notice error" role="alert">{{dialogError}}</p>
 <label>姓名<input v-model="form.employee_name" maxlength="100" required aria-label="姓名"></label>
 <label>生效日期<input type="date" v-model="form.movement_date" required aria-label="生效日期"></label>
 <template v-if="editing.movement_type==='promotion'"><label>升任後職位<select v-model="form.position" aria-label="升任後職位" @change="form.newbie_level=''"><option v-for="p in data.positions" :key="p">{{p}}</option></select></label><label v-if="['新人','行政'].includes(form.position)">新人／行政階級<select v-model="form.newbie_level" aria-label="新人／行政階級"><option value="">請選擇</option><option v-for="l in levelOptions" :key="l.value" :value="l.value">{{l.label}}</option></select></label></template>
 <label v-if="editing.movement_type==='onboarding'" class="check"><input type="checkbox" v-model="form.onboarding_is_pharmacist" aria-label="入職藥師身分">入職時為藥師</label>
 <label>備註<textarea v-model="form.notes" maxlength="5000" rows="3" aria-label="備註"></textarea></label>
 <p class="hint">儲存後會同步員工主檔與受影響月份的每月人員狀態；已送審／已確認月份不會被改動，會列入「需重新確認」。</p>
 <div class="dialog-actions"><button type="button" :disabled="saving" @click="editing=null">取消</button><button class="primary" :disabled="saving" data-testid="movement-edit-save">{{saving?'儲存中…':'儲存修改'}}</button></div></form></Modal>
<Modal v-if="removing" title="刪除異動紀錄" :busy="saving" @cancel="removing=null"><p v-if="dialogError" class="notice error" role="alert">{{dialogError}}</p>
 <p>確定刪除 {{removing.employee_name}}（{{removing.employee_code}}）{{dateTail(removing.movement_date)}} 的「{{removing.type_label}}」？刪除後會恢復員工主檔的狀態、門市與職位，並重算受影響月份的每月人員狀態（已送審／已確認月份只會列入需重新確認）。此動作無法復原。</p>
 <div class="dialog-actions"><button :disabled="saving" @click="removing=null">保留</button><button class="danger" :disabled="saving" data-testid="movement-delete-confirm" @click="confirmRemove">{{saving?'刪除中…':'確認刪除'}}</button></div></Modal>
</template><style scoped>.result-heading{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.filters{display:flex;flex-wrap:wrap;gap:16px;align-items:end;margin:24px 0}label{display:grid;gap:8px}.module-table table{min-width:1050px}.module-table td{white-space:normal;overflow-wrap:anywhere}.notes{white-space:pre-wrap!important;min-width:200px;max-width:360px}.actions{white-space:normal!important;min-width:120px}.actions button{margin:0 6px 6px 0}.hint{display:block;font-size:12px;color:var(--muted)}.edit-form{display:grid;gap:12px}.check{display:flex;align-items:center;gap:8px}.pagination{display:flex;gap:12px;align-items:center;margin-top:20px}.pagination span{margin-right:auto}@media(max-width:600px){.filters{display:grid;grid-template-columns:1fr 1fr}.filters label:first-child{grid-column:1/-1}input,select{width:100%;min-width:0}}</style>
